p.update(code='00908',protocol_id='nccp-00908-v1a',protocol_version='1b',content_version='0.84.23',suite_release='0.84.23',source_checked='2026-10-26',title='Serplulimab, carboplatin and etoposide',purpose='This treatment aims to control extensive-stage small-cell lung cancer, relieve symptoms and help people live longer. The balance of benefit, side effects and daily life is individual; it is generally not offered with an expectation of cure.',context_label='First-line extensive-stage small-cell lung cancer',indication_text='For adults starting drug treatment for extensive-stage small-cell lung cancer. This regimen does not require a minimum PD-L1 result.',schedule_summary=schedule,administration_text=admin,monitoring_summary='Blood counts, kidney and liver function and glucose are checked before each cycle. Thyroid tests are repeated every 3–6 weeks. The medicine information also recommends pancreatic enzyme checks at baseline and periodically. Other tests and scans depend on symptoms and the consultant plan.',service_kind='cytotoxic',schedule_kind='phased',cycle_display='reference-chronology')
p['agents'][0].update(alias='Hetronifly',mechanism='Blocks the PD-1 immune brake',explanation='Serplulimab is an antibody that blocks PD-1, a control switch on immune T cells. Some cancers use PD-L1 or PD-L2 to engage this switch and reduce the immune response. Blocking it can help immune cells attack cancer. The same immune activation can inflame healthy organs, so new symptoms need assessment even after treatment stops.',source_ids=['nccp','ema','serplulimab-smpc'],risks=['Immune inflammation of lungs, bowel, liver, kidneys, skin and hormone glands','Immune effects can also involve the heart, pancreas, nervous system or blood cells','Severe infusion reactions','Some hormone effects need lasting replacement treatment; immune effects can begin after the final dose'])
